var userConnection = Get<UserConnection>("UserConnection");

Guid leadId = Get<Guid>("LeadId");
Guid accountId = Get<Guid>("AccountId");

if (leadId == Guid.Empty || accountId == Guid.Empty) {
    return true;
}

try {
    Guid accountSchemaUId = userConnection.EntitySchemaManager.GetInstanceByName("Account").UId;

    // 1. SELECT ALL TOP-LEVEL POSTS FOR THE LEAD
    var selectPosts = new Terrasoft.Core.DB.Select(userConnection)
        .Column("Id")
        .Column("Message")
        .Column("CreatedById")
        .Column("CreatedOn")
        .From("SocialMessage")
        .Where("EntityId").IsEqual(Terrasoft.Core.DB.Column.Parameter(leadId))
        .And("ParentId").IsNull() as Terrasoft.Core.DB.Select;

    var postsToCopy = new System.Collections.Generic.List<Dictionary<string, object>>();

    using (Terrasoft.Core.DB.DBExecutor dbExecutor = userConnection.EnsureDBConnection()) {
        using (System.Data.IDataReader reader = selectPosts.ExecuteReader(dbExecutor)) {
            while (reader.Read()) {
                postsToCopy.Add(new Dictionary<string, object> {
                    { "Id", reader.GetColumnValue<Guid>("Id") },
                    { "Message", reader.GetColumnValue<string>("Message") ?? string.Empty },
                    { "CreatedById", reader.GetColumnValue<Guid>("CreatedById") },
                    { "CreatedOn", reader.GetColumnValue<DateTime>("CreatedOn") }
                });
            }
        }
    }

    // 2. PROCESS EACH POST
    foreach (var post in postsToCopy) {
        Guid oldPostId = (Guid)post["Id"];
        Guid newPostId = Guid.NewGuid();
        DateTime createdOn = (DateTime)post["CreatedOn"];

        // A. Fetch Comments
        var selectComments = new Terrasoft.Core.DB.Select(userConnection)
            .Column("Message")
            .Column("CreatedById")
            .Column("CreatedOn")
            .From("SocialMessage")
            .Where("ParentId").IsEqual(Terrasoft.Core.DB.Column.Parameter(oldPostId)) as Terrasoft.Core.DB.Select;

        var commentsToCopy = new System.Collections.Generic.List<Dictionary<string, object>>();
        using (Terrasoft.Core.DB.DBExecutor dbExecutor = userConnection.EnsureDBConnection()) {
            using (System.Data.IDataReader commentReader = selectComments.ExecuteReader(dbExecutor)) {
                while (commentReader.Read()) {
                    commentsToCopy.Add(new Dictionary<string, object> {
                        { "Message", commentReader.GetColumnValue<string>("Message") ?? string.Empty },
                        { "CreatedById", commentReader.GetColumnValue<Guid>("CreatedById") },
                        { "CreatedOn", commentReader.GetColumnValue<DateTime>("CreatedOn") }
                    });
                }
            }
        }

        // B. Fetch Likes
        var selectLikes = new Terrasoft.Core.DB.Select(userConnection)
            .Column("UserId")
            .From("SocialLike")
            .Where("SocialMessageId").IsEqual(Terrasoft.Core.DB.Column.Parameter(oldPostId)) as Terrasoft.Core.DB.Select;

        var likesToCopy = new System.Collections.Generic.List<Guid>();
        using (Terrasoft.Core.DB.DBExecutor dbExecutor = userConnection.EnsureDBConnection()) {
            using (System.Data.IDataReader likeReader = selectLikes.ExecuteReader(dbExecutor)) {
                while (likeReader.Read()) {
                    likesToCopy.Add(likeReader.GetColumnValue<Guid>("UserId"));
                }
            }
        }

        // C. Fetch Files specifically from [FeedFile] (Freedom UI Feed Attachment Table)
        var selectFeedFiles = new Terrasoft.Core.DB.Select(userConnection)
            .Column("Name")
            .Column("Data")
            .Column("Size")
            .Column("TypeId")
            .From("FeedFile")
            .Where("RecordId").IsEqual(Terrasoft.Core.DB.Column.Parameter(oldPostId)) as Terrasoft.Core.DB.Select;

        var filesToCopy = new System.Collections.Generic.List<Dictionary<string, object>>();
        using (Terrasoft.Core.DB.DBExecutor dbExecutor = userConnection.EnsureDBConnection()) {
            using (System.Data.IDataReader fileReader = selectFeedFiles.ExecuteReader(dbExecutor)) {
                while (fileReader.Read()) {
                    filesToCopy.Add(new Dictionary<string, object> {
                        { "Name", fileReader.GetColumnValue<string>("Name") },
                        { "Data", fileReader.GetColumnValue<byte[]>("Data") },
                        { "Size", fileReader.GetColumnValue<int>("Size") },
                        { "TypeId", fileReader.GetColumnValue<Guid>("TypeId") }
                    });
                }
            }
        }

        // D. Insert Parent Post
        new Terrasoft.Core.DB.Insert(userConnection)
            .Into("SocialMessage")
            .Set("Id", Terrasoft.Core.DB.Column.Parameter(newPostId))
            .Set("EntityId", Terrasoft.Core.DB.Column.Parameter(accountId))
            .Set("EntitySchemaUId", Terrasoft.Core.DB.Column.Parameter(accountSchemaUId))
            .Set("Message", Terrasoft.Core.DB.Column.Parameter(post["Message"]))
            .Set("CreatedById", Terrasoft.Core.DB.Column.Parameter(post["CreatedById"]))
            .Set("CreatedOn", Terrasoft.Core.DB.Column.Parameter(createdOn))
            .Set("LastActionOn", Terrasoft.Core.DB.Column.Parameter(createdOn))
            .Set("CommentCount", Terrasoft.Core.DB.Column.Parameter(commentsToCopy.Count))
            .Set("LikeCount", Terrasoft.Core.DB.Column.Parameter(likesToCopy.Count))
            .Execute();

        // E. Insert Threaded Comments
        foreach (var comment in commentsToCopy) {
            DateTime commentCreatedOn = (DateTime)comment["CreatedOn"];
            new Terrasoft.Core.DB.Insert(userConnection)
                .Into("SocialMessage")
                .Set("Id", Terrasoft.Core.DB.Column.Parameter(Guid.NewGuid()))
                .Set("EntityId", Terrasoft.Core.DB.Column.Parameter(accountId))
                .Set("EntitySchemaUId", Terrasoft.Core.DB.Column.Parameter(accountSchemaUId))
                .Set("ParentId", Terrasoft.Core.DB.Column.Parameter(newPostId))
                .Set("Message", Terrasoft.Core.DB.Column.Parameter(comment["Message"]))
                .Set("CreatedById", Terrasoft.Core.DB.Column.Parameter(comment["CreatedById"]))
                .Set("CreatedOn", Terrasoft.Core.DB.Column.Parameter(commentCreatedOn))
                .Set("LastActionOn", Terrasoft.Core.DB.Column.Parameter(commentCreatedOn))
                .Execute();
        }

        // F. Insert Likes
        foreach (var userId in likesToCopy) {
            new Terrasoft.Core.DB.Insert(userConnection)
                .Into("SocialLike")
                .Set("Id", Terrasoft.Core.DB.Column.Parameter(Guid.NewGuid()))
                .Set("SocialMessageId", Terrasoft.Core.DB.Column.Parameter(newPostId))
                .Set("UserId", Terrasoft.Core.DB.Column.Parameter(userId))
                .Execute();
        }

        // G. Insert File Attachments into [FeedFile] and [SysFile]
        foreach (var file in filesToCopy) {
            Guid newFileId = Guid.NewGuid();

            // Insert into FeedFile (Exact Freedom UI Feed Attachment schema)
            new Terrasoft.Core.DB.Insert(userConnection)
                .Into("FeedFile")
                .Set("Id", Terrasoft.Core.DB.Column.Parameter(newFileId))
                .Set("RecordId", Terrasoft.Core.DB.Column.Parameter(newPostId))
                .Set("RecordSchemaName", Terrasoft.Core.DB.Column.Parameter("SocialMessage"))
                .Set("Name", Terrasoft.Core.DB.Column.Parameter(file["Name"]))
                .Set("Data", Terrasoft.Core.DB.Column.Parameter(file["Data"]))
                .Set("Size", Terrasoft.Core.DB.Column.Parameter(file["Size"]))
                .Set("TypeId", Terrasoft.Core.DB.Column.Parameter(file["TypeId"]))
                .Execute();

            // Insert into SysFile as backup
            try {
                new Terrasoft.Core.DB.Insert(userConnection)
                    .Into("SysFile")
                    .Set("Id", Terrasoft.Core.DB.Column.Parameter(newFileId))
                    .Set("RecordId", Terrasoft.Core.DB.Column.Parameter(newPostId))
                    .Set("RecordSchemaName", Terrasoft.Core.DB.Column.Parameter("SocialMessage"))
                    .Set("Name", Terrasoft.Core.DB.Column.Parameter(file["Name"]))
                    .Set("Data", Terrasoft.Core.DB.Column.Parameter(file["Data"]))
                    .Set("Size", Terrasoft.Core.DB.Column.Parameter(file["Size"]))
                    .Set("TypeId", Terrasoft.Core.DB.Column.Parameter(file["TypeId"]))
                    .Execute();
            } catch { }
        }
    }
} catch (Exception ex) {
    var logger = global::Common.Logging.LogManager.GetLogger("Process");
    logger.Error($"Feed Copy Error: {ex.Message}", ex);
}

return true;
